(() => {
  const root=window.TitanWorkCore=window.TitanWorkCore||{}; const DB=()=>root.db,S=()=>root.contracts.stores;
  async function serviceWorkerVersion(){if(!navigator.serviceWorker?.controller)return null;return new Promise(resolve=>{const channel=new MessageChannel(),timer=setTimeout(()=>resolve(null),1500);channel.port1.onmessage=e=>{clearTimeout(timer);resolve(e.data?.version||null)};navigator.serviceWorker.controller.postMessage({type:'GET_VERSION'},[channel.port2]);});}
  async function inspect(){let database='healthy';try{await DB().open();await DB().getMeta('integrity_last_check')}catch(_){database='error'} const [attachments,knowledge,packs,outbox,storage,sw]=await Promise.all([DB().all(S().attachments),DB().all(S().knowledgeArticles),DB().all(S().offlinePacks),DB().all(S().outbox),root.storageManager.usage(),serviceWorkerVersion()]);const result={applicationShell:Boolean(await caches.match('/chatbot-pwa/offline.html')),database,vault:root.security?.vault?.state||'unknown',conversations:(await DB().all(S().records)).length,knowledge:knowledge.length,attachments:{available:attachments.length,pending:attachments.filter(a=>a.state!=='synced').length},offlinePacks:{ready:packs.filter(p=>p.status==='ready').length,total:packs.length},unsynchronised:outbox.filter(o=>!['sent','cancelled','synced'].includes(o.state)).length,lastSync:await DB().getMeta('last_successful_sync'),storage,serviceWorkerVersion:sw,databaseVersion:root.contracts.database.version,serverReachable:await root.network.checkReachability()};window.dispatchEvent(new CustomEvent('workcore:readiness',{detail:result}));return result;}
  root.readiness={inspect};
})();
